/* Explicit software CP clock; no writes to AP clock or original CP address. */
struct date99_clock{W initialized,valid,reason,pad;U generation,basis_ns;long utc_ms;B native_date[16],timezone[8];};
static int c99_leap(int y){return y%4==0&&(y%100!=0||y%400==0);}static int c99_dim(int y,int m){const B t[12]={31,28,31,30,31,30,31,31,30,31,30,31};return t[m-1]+(m==2&&c99_leap(y));}
static long c99_days0(int y){long z=y-1;return z*365+z/4-z/100+z/400;}
static int c99_decode(const B*d,const B*tz,long*out){int y=rd16(d),m=d[2],day=d[3],h=d[4],mi=d[5],s=d[6],ms=rd16(d+8),type=d[12];int td=(short)rd16(tz),dst=(short)rd16(tz+2);if(y<1||y>9999||m<1||m>12||day<1||day>c99_dim(y,m)||h>23||mi>59||s>59||ms>999||type>1||rd16(tz+4)||td< -1440||td>1440||dst< -1440||dst>1440)return -1021;long days=c99_days0(y)-c99_days0(1970)+day-1;for(int i=1;i<m;i++)days+=c99_dim(y,i);long value=((days*24+h)*60+mi)*60000+s*1000+ms;if(type==0)value-=(long)(td+dst)*60000;*out=value;return 0;}
static int c99_build(struct date99_clock*out,const B*d,const B*tz,W reason,U start,U now,U generation){if(!out||!d||!tz||now<start||!reason||reason>8)return -1021;struct date99_clock n={0};n.initialized=1;n.reason=reason;n.generation=generation;n.basis_ns=now-(now-start)/2;cp_copy(n.native_date,d,16);cp_copy(n.timezone,tz,8);if(d[12]>=2){if(reason!=4||d[12]>3)return -1021;n.valid=0;}else{if(c99_decode(d,tz,&n.utc_ms))return -1021;n.valid=1;}*out=n;return 0;}
static int c99_read(const struct date99_clock*c,U now,B*out,long*utc){if(!c||!c->initialized||!out||now<c->basis_ns)return -1021;if(!c->valid){cp_copy(out,c->native_date,16);if(utc)*utc=0;return 0;}long v=c->utc_ms+(long)((now-c->basis_ns)/1000000UL);if(utc)*utc=v;v+=(long)((short)rd16(c->timezone)+(short)rd16(c->timezone+2))*60000;long days=v/86400000L,rem=v%86400000L;if(rem<0){days--;rem+=86400000L;}long absolute=days+c99_days0(1970);if(absolute<0||absolute>=c99_days0(10000))return -1021;int lo=1,hi=10000;while(lo+1<hi){int mid=(lo+hi)/2;if(c99_days0(mid)<=absolute)lo=mid;else hi=mid;}int m=1;long doy=absolute-c99_days0(lo);while(doy>=c99_dim(lo,m)){doy-=c99_dim(lo,m);m++;}for(int i=0;i<16;i++)out[i]=0;out[0]=lo&255;out[1]=lo>>8;out[2]=m;out[3]=doy+1;out[4]=rem/3600000L;out[5]=rem/60000L%60;out[6]=rem/1000L%60;out[8]=rem%1000;out[9]=(rem%1000)>>8;out[12]=0;return 0;}
